from rules import amount


def solve(data):
    balances = dict(data.get('opening', {}))
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data.get('events', [])):
        if event.get('sequence', 0) > cutoff:
            continue
        event_id = event.get('id')
        identity = ('anonymous', position) if event_id is None else ('id', event_id)
        revision = event.get('revision', 0)
        current = winners.get(identity)
        if current is None or (revision, position) >= (current[0], current[1]):
            winners[identity] = (revision, position, event)

    for _, _, event in winners.values():
        if event.get('void', False) is True:
            continue
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances[key] = balances.get(key, 0) + amount(event, data.get('rounding', 'floor'))

    return {'balances': balances}
